-- TomoModForever 1.4.1: TMF's own action bars, Forever ornate skin, shine
-- and halo animations, quick keybind mode (Core/WhatsNew.lua).
-- No "+", guillemets or bullets in these strings: the font may not carry them.

TomoMod_RegisterLocale("enUS", {
    ["wn_141_bars"] = "New - TMF action bars: the game's buttons move into TMF's own bars. Pick each bar's size, button count, buttons per row and spacing, and drag them anywhere in Layout mode. Spells, macros, keybinds, pet, stance and totem bars all keep working. Off by default: Action bars, TMF bars. On the first turn-on the bars stay where they were.",
    ["wn_141_ornate"] = "New - Forever ornate skin for the action buttons: bronze and gold frame with a soft golden halo under the mouse. A golden gleam also crosses an icon when a long cooldown is ready again (can be turned off). Both follow the animation setting.",
    ["wn_141_kb"] = "Changed - /kb now opens the quick keybind mode: hover a button and press a key. Also a Keybinds button in Action bars.",
})
TomoMod_RegisterLocale("frFR", {
